@layer material, material-high-contrast, size;

:is(:root,:host) {
	--db-focus-outline-color: light-dark(#257FA8, #257FA8);
	--db-divider-bg-color: light-dark(#5A5E68, #8A919E);
	--db-color-transparency: 100%;
	--db-font-weight: normal;
}

@layer material {

:is(:root,:host) {
	--db-border: color-mix(in srgb, light-dark(#16181B, #F3F3F5) var(--db-color-transparency), transparent);
	--db-bg-default: color-mix(in srgb, light-dark(#FFFFFF, #0D0E11) var(--db-color-transparency), transparent);
	--db-bg-hovered: color-mix(in srgb, light-dark(#E1E2E6, #2E3036) var(--db-color-transparency), transparent);
	--db-bg-pressed: color-mix(in srgb, light-dark(#C3C7CE, #3B3E44) var(--db-color-transparency), transparent);
	--db-border-vibrant: color-mix(in srgb, light-dark(#727782, #727782) var(--db-color-transparency), transparent);
	--db-border-decorative: color-mix(in srgb, light-dark(#E1E2E6, #2E3036) var(--db-color-transparency), transparent);
	--db-on-bg-default: color-mix(in srgb, light-dark(#16181B, #F3F3F5) var(--db-color-transparency), transparent);
	--db-on-bg-hovered: color-mix(in srgb, light-dark(#484B53, #A6ABB6) var(--db-color-transparency), transparent);
	--db-on-bg-pressed: color-mix(in srgb, light-dark(#222428, #EDEEF0) var(--db-color-transparency), transparent);
	--db-text-vibrant: color-mix(in srgb, light-dark(#5A5E68, #8A919E) var(--db-color-transparency), transparent);
	--db-visual-vibrant: color-mix(in srgb, light-dark(#727782, #727782) var(--db-color-transparency), transparent);
}

